-- Outreach templates: the agency's first email per job (sourcing template.ts).
alter table public.jobs add column if not exists outreach_template jsonb;

-- The agency's own templates for the roles open on 16 Oct 2026 (client names left out; pay and
-- location as on each ProNext job).
update public.jobs set outreach_template = $tpl${"subject": "Gas Safe Plumber – £25-30K, Croydon (Hybrid)", "body": "Hi [First Name],\n\nI came across your profile while searching for Gas Safe plumbers in the London area.\n\nWe're working on a Plumber role:\n- **Location:** Croydon (Hybrid – 3 days on-site, 2 remote)\n- **Salary:** £25,000 - £30,000\n- **Requirements:** Gas Safe + G3 certified, boiler servicing & CP12 inspections\n\nYour [specific skill/experience from their profile] caught my attention.\n\nIf you're open to exploring it, you can apply here: {{APPLY_LINK}}\n\nHappy to answer any questions.\n\nAhmed", "source": "agency", "at": "2026-10-16T09:00:00Z"}$tpl$::jsonb where id = '47d239ef-ab15-4661-b284-e2aecea92b50';
update public.jobs set outreach_template = $tpl${"subject": "Qualified Electrician – £25-30K, Croydon (Hybrid)", "body": "Hi [First Name],\n\nI came across your profile while searching for qualified electricians in the London area.\n\nWe're working on a Qualified Electrician role:\n- **Location:** Croydon (Hybrid)\n- **Salary:** £25,000 - £30,000\n- **Requirements:** ECS Gold Card, NICEIC/NAPIT registration, EICRs & PAT testing\n\nYour [specific skill/experience from their profile] stood out.\n\nIf you're interested, you can apply here: {{APPLY_LINK}}\n\nLet me know if you have any questions.\n\nAhmed", "source": "agency", "at": "2026-10-16T09:00:00Z"}$tpl$::jsonb where id = '89f9b2ac-3dca-4b02-886b-5f2bc144cf34';
update public.jobs set outreach_template = $tpl${"subject": "Taiwanese Customer Service Specialist – RM 8,500-8,900, Penang", "body": "Hi [First Name],\n\nI came across your profile while searching for native Taiwanese speakers in Malaysia.\n\nWe're working on a Customer Service Specialist role:\n- **Location:** Penang, Malaysia (On-site)\n- **Salary:** RM 8,500 - RM 8,900 (includes language allowance)\n- **Requirements:** Native Taiwanese speaker, degree holder, rotating shifts\n\nYour [specific skill/experience from their profile] looks like a great match.\n\nIf you're interested, you can apply here: {{APPLY_LINK}}\n\nHappy to answer any questions.\n\nAhmed", "source": "agency", "at": "2026-10-16T09:00:00Z"}$tpl$::jsonb where id = '3e198a44-a567-4af7-9a7b-5835961d519d';
update public.jobs set outreach_template = $tpl${"subject": "Cantonese Bilingual CS Rep – Makati (Contract, Start Nov 2)", "body": "Hi [First Name],\n\nI came across your profile while searching for Cantonese speakers in the Philippines.\n\nWe're working on a Customer Service Representative role:\n- **Location:** Makati (On-site, shifting schedule)\n- **Contract:** Project-based, supporting 24/7 operations\n- **Requirements:** Cantonese + English fluency, 2-3 years experience, start by Nov 2\n\nYour [specific skill/experience from their profile] caught my attention.\n\nIf you're open to it, you can apply here: {{APPLY_LINK}}\n\nLet me know if you have questions.\n\nAhmed", "source": "agency", "at": "2026-10-16T09:00:00Z"}$tpl$::jsonb where id = 'e50620ec-7694-4948-8230-b7ff514a8e67';
update public.jobs set outreach_template = $tpl${"subject": "Contract Staff Accountant – $24/hr, Urbandale (6 days/month onsite)", "body": "Hi [First Name],\n\nI came across your profile while searching for accountants with collections experience in Iowa.\n\nWe're working on a Contract Staff Accountant role:\n- **Location:** Urbandale, Iowa (6 days/month onsite)\n- **Rate:** $24/hour\n- **Requirements:** 1-3 years collections/finance experience, intermediate Excel skills\n\nYour [specific skill/experience from their profile] looks like a strong fit.\n\nIf you're interested, you can apply here: {{APPLY_LINK}}\n\nHappy to answer any questions.\n\nAhmed", "source": "agency", "at": "2026-10-16T09:00:00Z"}$tpl$::jsonb where id = '967b6fea-06c9-4dbe-b4f6-60039da9a9e4';
update public.jobs set outreach_template = $tpl${"subject": "Finance Channel Partner Manager – 15-20K SAR, Riyadh", "body": "Hi [First Name],\n\nI came across your profile while searching for channel sales professionals with finance software experience in Saudi Arabia.\n\nWe're working on a Finance Channel Partner Manager role:\n- **Location:** Riyadh (Onsite)\n- **Salary:** 15,000 - 20,000 SAR/month\n- **Requirements:** 3-5 years channel sales, accounting software knowledge, fluent Arabic + English\n\nYour [specific skill/experience from their profile] stood out.\n\nIf you're open to exploring it, you can apply here: {{APPLY_LINK}}\n\nLet me know if you have any questions.\n\nAhmed", "source": "agency", "at": "2026-10-16T09:00:00Z"}$tpl$::jsonb where id = '63a95345-a111-490d-8a2a-a46a057ac075';
update public.jobs set outreach_template = $tpl${"subject": "Remote Customer Service Rep – $40-80K (Work from Home, USA)", "body": "Hi [First Name],\n\nI came across your profile while searching for remote customer service professionals in the United States.\n\nWe're working on a Remote Customer Service Representative role:\n- **Location:** Remote (USA-based)\n- **Salary:** $40,000 - $80,000/year\n- **Requirements:** 1-3 years customer service experience, full-time permanent\n\nYour [specific skill/experience from their profile] looks like a great match.\n\nIf you're interested, you can apply here: {{APPLY_LINK}}\n\nHappy to answer any questions.\n\nAhmed", "source": "agency", "at": "2026-10-16T09:00:00Z"}$tpl$::jsonb where id = 'acf2f7d1-3fcf-4e72-a647-23e1f4c88c9f';
update public.jobs set outreach_template = $tpl${"subject": "CPA – $91-120K, Kalispell, MT (Public Accounting)", "body": "Hi [First Name],\n\nI came across your profile while searching for CPAs with public accounting experience in Montana.\n\nWe're working on a CPA role:\n- **Location:** Kalispell, MT (Onsite)\n- **Salary:** $91,000 - $120,000/year\n- **Requirements:** Active CPA license, 3+ years public accounting, tax preparation & review experience\n\nYour [specific skill/experience from their profile] caught my attention.\n\nIf you're open to exploring it, you can apply here: {{APPLY_LINK}}\n\nLet me know if you have any questions.\n\nAhmed", "source": "agency", "at": "2026-10-16T09:00:00Z"}$tpl$::jsonb where id = 'b9b3ab14-6269-447c-86ac-6cbfe11556dd';
update public.jobs set outreach_template = $tpl${"subject": "Litigation Attorney – $110-180K, Virginia", "body": "Hi [First Name],\n\nI came across your profile while searching for construction litigation attorneys in Virginia.\n\nWe're working on an Associate Litigation Attorney role:\n- **Location:** Virginia\n- **Salary:** $110,000 - $180,000/year\n- **Requirements:** 2+ years construction/homeowner litigation, active Virginia bar license\n\nYour [specific skill/experience from their profile] stood out.\n\nIf you're interested, you can apply here: {{APPLY_LINK}}\n\nHappy to answer any questions.\n\nAhmed", "source": "agency", "at": "2026-10-16T09:00:00Z"}$tpl$::jsonb where id = 'e2524535-1002-4d27-bd39-450cac5f7543';
