update public.jobs set outreach_template = $tpl${"subject": "Lead Planner / Service Advisor – $121-150K, Buffalo Grove, IL (Onsite)", "body": "Hi [First Name],\n\nI came across your profile while searching for service advisors with scheduling experience.\n\nWe're working on a Lead Planner / Service Advisor role:\n- **Location:** Buffalo Grove, Illinois (Onsite)\n- **Salary:** $121,000 - $150,000/year\n- **Requirements:** 2+ years scheduling/planning, customer service background\n\nYour [specific skill/experience from their profile] caught my attention.\n\nIf you're interested, you can apply here: {{APPLY_LINK}}\n\nHappy to answer any questions.\n\nAhmed", "source": "agency", "at": "2026-10-16T09:00:00Z"}$tpl$::jsonb where id = '93063bd0-ccc0-4916-b4e6-bb2baebb5d9c';
update public.jobs set outreach_template = $tpl${"subject": "Compensation Consultant – $121-200K, Washington, DC (Hybrid)", "body": "Hi [First Name],\n\nI came across your profile while searching for compensation consultants with benefits experience.\n\nWe're working on a Compensation Consultant role:\n- **Location:** Washington, DC (Hybrid)\n- **Salary:** $121,000 - $200,000/year\n- **Requirements:** 3+ years compensation consulting, benefits design, salary benchmarking\n\nYour [specific skill/experience from their profile] stood out.\n\nIf you're open to exploring it, you can apply here: {{APPLY_LINK}}\n\nLet me know if you have any questions.\n\nAhmed", "source": "agency", "at": "2026-10-16T09:00:00Z"}$tpl$::jsonb where id = '8899af24-9024-4f62-a40f-9dbd6db4901d';
update public.jobs set outreach_template = $tpl${"subject": "Executive Accountant – £25-30K, Croydon (Onsite)", "body": "Hi [First Name],\n\nI came across your profile while searching for accountants with facilities management experience.\n\nWe're working on an Executive Accountant role:\n- **Location:** Croydon, United Kingdom (Onsite)\n- **Salary:** £25,000 - £30,000\n- **Requirements:** 3+ years accounting, facilities/property management background preferred\n\nYour [specific skill/experience from their profile] looks like a strong match.\n\nIf you're interested, you can apply here: {{APPLY_LINK}}\n\nHappy to answer any questions.\n\nAhmed", "source": "agency", "at": "2026-10-16T09:00:00Z"}$tpl$::jsonb where id = 'aea2e2f9-8292-4ff9-97e0-e342e0d83780';
